import coreWebVitals from 'eslint-config-next/core-web-vitals';
import nextTypescript from 'eslint-config-next/typescript';
import prettier from 'eslint-config-prettier';

/**
 * eslint-config-next 16 ships native flat configs, so the FlatCompat shim it previously needed is
 * gone along with its @eslint/eslintrc dependency. Wrapping the v16 configs in FlatCompat throws
 * on a circular structure, because the legacy validator cannot serialize a flat config.
 */
const config = [
  ...coreWebVitals,
  ...nextTypescript,
  prettier,
  {
    // next-env.d.ts is regenerated by `next build` and its contents are not ours to fix.
    ignores: ['.next/**', 'node_modules/**', 'scripts/**', 'next-env.d.ts'],
  },
  {
    rules: {
      '@typescript-eslint/no-unused-vars': ['error', { argsIgnorePattern: '^_' }],
      'no-console': ['error', { allow: ['log', 'warn', 'error'] }],
    },
  },
];

export default config;
